module tb;
  reg [3:0] a, b; wire [4:0] sum; integer i, j, errors;
  adder4 dut(.a(a), .b(b), .sum(sum));
  initial begin
    errors = 0;
    for (i = 0; i < 16; i = i + 1)
      for (j = 0; j < 16; j = j + 1) begin
        a = i[3:0]; b = j[3:0]; #1;
        if (sum !== (i + j)) begin
          errors = errors + 1;
          $display("FAIL a=%0d b=%0d sum=%0d", i, j, sum);
        end
      end
    if (errors == 0) $display("ALL_TESTS_PASSED");
    $finish;
  end
endmodule
